#include "world_damage_storage.hpp"
#include "universe.hpp"
#include <stdexcept>
namespace hyperion {
using J=nlohmann::json;
J encodeWorldDamage(const WorldDamageMap& map){J out=J::object();for(const auto& [id,d]:map){out[id]={{"star",d.star},{"owner",d.owner},{"kind",d.kind},{"body",d.body},{"slot",d.slot},{"good",d.good},{"integrity",d.integrity},{"scale",d.scale},{"position",{d.position.x,d.position.y,d.position.z}},{"normal",{d.normal.x,d.normal.y,d.normal.z}},{"salvage",d.salvage}};
 if(d.structure.valid){const auto& f=d.structure;auto vec=[](flight::V3 v){return J::array({v.x,v.y,v.z});};out[id]["structure"]={{"profile",f.profile},{"faction",f.faction},{"variant",f.variant},{"ordinal",f.ordinal},{"seed",f.seed},{"orbital",f.orbital},{"born",f.born},{"origin",vec(f.origin)},{"right",vec(f.right)},{"up",vec(f.up)},{"back",vec(f.back)},{"impact",vec(f.impact)}};
 if(f.localized)out[id]["structure"]["localized"]={{"centre",vec(f.hitCentre)},{"half",vec(f.hitHalf)},{"sections",f.sections},{"separated",f.separated},{"cleared",f.cleared},{"debrisHP",f.debrisHP}};
 }
 if(d.recovery.valid){const auto& r=d.recovery;out[id]["recovery"]={{"stabilized",r.stabilized},{"cut",r.cut},{"box",r.box},{"boxRecovered",r.boxRecovered},{"failed",r.failed},{"towed",r.towed},{"culprit",r.culprit},{"faction",r.faction},{"initialCrew",r.initialCrew},{"crew",r.crew},{"aboard",r.aboard},{"delivered",r.delivered},{"lost",r.lost},{"born",r.born},{"charge",r.charge},{"failureAt",r.failureAt},{"supportUntil",r.supportUntil},{"sealed",r.sealed},{"initial",r.initial},{"recovered",r.recovered},{"destroyed",r.destroyed},{"shipId",r.shipId},{"shipModel",r.shipModel},{"shipSeed",r.shipSeed},{"shipForward",{r.shipForward.x,r.shipForward.y,r.shipForward.z}},{"towOffset",{r.towOffset.x,r.towOffset.y,r.towOffset.z}}};}
 }return out;}
WorldDamageMap decodeWorldDamage(const J& j,Universe& universe,double hour){
 if(!j.is_object()||j.size()>60000)throw std::runtime_error("Invalid world destruction ledger");WorldDamageMap map;
 for(auto it=j.begin();it!=j.end();++it){const auto& v=it.value();WorldDamage d;auto id=it.key();if(id.empty()||id.size()>512||!v.is_object())throw std::runtime_error("Invalid destructible identity");
  auto number=[&](const char* key,double low,double high){double n=v.at(key).get<double>();if(!std::isfinite(n)||n<low||n>high)throw std::runtime_error(std::string("Invalid world damage field: ")+key);return n;};
  auto integer=[&](const char* key,int low,int high){double n=number(key,low,high);if(n!=std::floor(n))throw std::runtime_error("Fractional world damage index");return int(n);};
  d.star=v.at("star").get<std::string>();d.owner=v.at("owner").get<std::string>();if(d.star.size()>100||d.owner.size()>512||universe.star(d.star).id!=d.star)throw std::runtime_error("Invalid destruction system");
  d.kind=integer("kind",FacilityObject,SalvageObject);d.body=integer("body",-1,int(universe.planets(d.star).size())-1);d.slot=integer("slot",-1,100000);d.good=integer("good",-1,8);d.integrity=number("integrity",0,1);d.scale=number("scale",.01,4096);
  auto vector=[&](const char* key){const auto& a=v.at(key);if(!a.is_array()||a.size()!=3)throw std::runtime_error("Invalid damage vector");flight::V3 p{a[0].get<double>(),a[1].get<double>(),a[2].get<double>()};if(!flight::finite(p)||flight::length(p)>1e8)throw std::runtime_error("Nonfinite damage position");return p;};
  d.position=vector("position");d.normal=vector("normal");if(flight::length(d.normal)<.9||flight::length(d.normal)>1.1)throw std::runtime_error("Invalid damage orientation");
  const auto& cargo=v.at("salvage");if(!cargo.is_array()||cargo.size()!=9)throw std::runtime_error("Invalid debris cargo");for(int i=0;i<9;i++){d.salvage[i]=cargo[i].get<double>();if(!std::isfinite(d.salvage[i])||d.salvage[i]<0||d.salvage[i]>500)throw std::runtime_error("Invalid debris supply");}
  if(v.contains("structure")){
   const auto& f=v.at("structure");auto& shape=d.structure;if(!f.is_object()||(d.integrity>0&&!f.contains("localized")))throw std::runtime_error("Invalid structural ruin");
   auto scalar=[&](const char* key,double low,double high,bool integral=false){double n=f.at(key).get<double>();if(!std::isfinite(n)||n<low||n>high||(integral&&n!=std::floor(n)))throw std::runtime_error("Invalid structural field");return n;};
   auto vector=[&](const char* key){const auto& a=f.at(key);if(!a.is_array()||a.size()!=3)throw std::runtime_error("Invalid structural vector");flight::V3 n{a[0].get<double>(),a[1].get<double>(),a[2].get<double>()};if(!flight::finite(n)||flight::length(n)>1e8)throw std::runtime_error("Invalid structural vector");return n;};
   shape.ordinal=int(scalar("ordinal",0,23,true));shape.profile=int(scalar("profile",0,flight::StructureProfileCount-1,true));shape.faction=int(scalar("faction",0,4,true));shape.variant=int(scalar("variant",-1,100000,true));shape.seed=uint32_t(scalar("seed",0,4294967295.,true));shape.born=scalar("born",0,hour);shape.orbital=f.at("orbital").get<bool>();
   shape.origin=vector("origin");shape.right=vector("right");shape.up=vector("up");shape.back=vector("back");shape.impact=vector("impact");
   if(std::abs(flight::length(shape.right)-1)>1e-5||std::abs(flight::length(shape.up)-1)>1e-5||std::abs(flight::length(shape.back)-1)>1e-5||flight::length(flight::cross(shape.right,shape.up)-shape.back)>1e-5||flight::length(shape.impact)>8192||flight::length(shape.origin-d.position)>2048)throw std::runtime_error("Invalid structural frame");
   bool orbital=shape.profile==flight::StationCore||shape.profile==flight::StationWing;
   bool compatible=d.kind==FacilityObject?shape.profile<14&&d.slot/24==shape.profile:d.kind==PortObject?shape.profile==flight::StationCore||shape.profile==flight::LandingPad:d.kind==CargoObject?shape.profile==flight::FreightCrate:d.kind==PanelObject?shape.profile==flight::StationWing||shape.profile==flight::LoadingGantry||shape.profile==flight::PortMast||shape.profile==flight::PortTerminal:false;
   if(!compatible||shape.orbital!=orbital||(shape.profile==flight::FreightCrate&&(shape.variant<0||shape.variant>8))||(shape.profile==flight::StationWing&&std::abs(shape.variant)!=1)||(shape.profile==flight::StationCore&&(shape.variant<0||shape.variant>80||(shape.variant&15)>8))||(shape.profile<14&&(shape.variant<0||shape.variant>12||shape.ordinal!=d.slot%24)))throw std::runtime_error("Invalid structural identity");shape.valid=true;
  }
  if(d.structure.valid&&v["structure"].contains("localized")){
   auto& f=d.structure;const auto& a=v["structure"]["localized"];f.localized=true;
   auto vec=[&](const char* key){const auto& p=a.at(key);if(!p.is_array()||p.size()!=3)throw std::runtime_error("Invalid section frame");flight::V3 n{p[0].get<double>(),p[1].get<double>(),p[2].get<double>()};if(!flight::finite(n)||flight::length(n)>8192)throw std::runtime_error("Invalid section bounds");return n;};f.hitCentre=vec("centre");f.hitHalf=vec("half");if(std::min({f.hitHalf.x,f.hitHalf.y,f.hitHalf.z})<=0)throw std::runtime_error("Empty section bounds");
   auto array=[&](const char* key,auto& target,double low,double high){const auto& list=a.at(key);if(!list.is_array()||list.size()!=target.size())throw std::runtime_error("Invalid section array");for(size_t i=0;i<target.size();i++){double x=list[i].template get<double>();if(!std::isfinite(x)||x<low||x>high)throw std::runtime_error("Invalid section value");target[i]=x;}};array("sections",f.sections,0,1);array("separated",f.separated,-1,hour);array("debrisHP",f.debrisHP,0,1);double mask=a.at("cleared").get<double>();if(!std::isfinite(mask)||mask<0||mask>=double(1u<<(9*flight::structureRows(f)))||std::floor(mask)!=mask)throw std::runtime_error("Invalid fragment mask");f.cleared=uint32_t(mask);
   for(int i=0;i<6;i++)if((f.sections[i]<=0)!=(f.separated[i]>=f.born)|| (d.integrity<=0&&f.sections[i]>0))throw std::runtime_error("Invalid section chronology");
   for(int i=0;i<9*flight::structureRows(f);i++)if(bool(f.cleared&(1u<<i))!=(f.debrisHP[i]<=0))throw std::runtime_error("Invalid fragment integrity");
  }
  if(v.contains("recovery")){
   const auto& a=v.at("recovery");auto& r=d.recovery;auto n=[&](const char* key,double low,double high,bool integral=false){double x=a.at(key).get<double>();if(!std::isfinite(x)||x<low||x>high||(integral&&x!=std::floor(x)))throw std::runtime_error("Invalid recovery value");return x;};r.valid=true;r.stabilized=a.at("stabilized").get<bool>();r.cut=a.at("cut").get<bool>();r.box=a.at("box").get<bool>();r.boxRecovered=a.at("boxRecovered").get<bool>();r.failed=a.at("failed").get<bool>();r.towed=a.at("towed").get<bool>();r.culprit=a.at("culprit").get<std::string>();r.faction=int(n("faction",0,4,true));r.initialCrew=int(n("initialCrew",0,24,true));r.crew=int(n("crew",0,24,true));r.aboard=int(n("aboard",0,24,true));r.delivered=int(n("delivered",0,24,true));r.lost=int(n("lost",0,24,true));r.born=n("born",0,hour);r.charge=n("charge",0,1);r.failureAt=n("failureAt",0,1e12);r.supportUntil=n("supportUntil",r.born,1e12);
   for(auto pair:{std::make_pair("sealed",&r.sealed),std::make_pair("initial",&r.initial),std::make_pair("recovered",&r.recovered),std::make_pair("destroyed",&r.destroyed)}){const auto& list=a.at(pair.first);if(!list.is_array()||list.size()!=9)throw std::runtime_error("Invalid recovery inventory");for(int i=0;i<9;i++){double x=list[i].get<double>();if(!std::isfinite(x)||x<0||x>500)throw std::runtime_error("Invalid recovery stock");(*pair.second)[i]=x;}}
   r.shipId=a.at("shipId").get<std::string>();r.shipModel=int(n("shipModel",-1,255,true));r.shipSeed=uint32_t(n("shipSeed",0,4294967295.,true));auto forward=a.at("shipForward");if(!forward.is_array()||forward.size()!=3)throw std::runtime_error("Invalid wreck attitude");r.shipForward={forward[0].get<double>(),forward[1].get<double>(),forward[2].get<double>()};if(!flight::finite(r.shipForward)||std::abs(flight::length(r.shipForward)-1)>.00001||r.shipId.size()>512)throw std::runtime_error("Invalid wreck identity");
   auto offset=a.at("towOffset");if(!offset.is_array()||offset.size()!=3)throw std::runtime_error("Invalid tow offset");r.towOffset={offset[0].get<double>(),offset[1].get<double>(),offset[2].get<double>()};if(!flight::finite(r.towOffset)||flight::length(r.towOffset)>55.001)throw std::runtime_error("Invalid tow tether");
   if(d.integrity>0||r.culprit.size()>512||r.initialCrew!=r.crew+r.aboard+r.delivered+r.lost||(r.boxRecovered&&!r.box)||(r.towed&&(((!d.structure.valid||!d.structure.orbital)&&r.shipModel<0)||!r.stabilized)))throw std::runtime_error("Inconsistent recovery state");for(int i=0;i<9;i++)if(std::abs(r.sealed[i]+r.recovered[i]+r.destroyed[i]-r.initial[i])>1e-6)throw std::runtime_error("Recovery stock not conserved");
  }
  if(d.kind==FacilityObject&&(!d.structure.valid||id!=facilityObjectId(d.owner,d.slot/24,d.slot%24)))throw std::runtime_error("Invalid facility ruin");
  map.emplace(id,std::move(d));
 }return map;
}
}
